import os

def calculate_total_sales(directory, start_month, end_month):
    total_sum = 0
    files_processed = 0

    # 遍历目录下的所有文件
    for filename in sorted(os.listdir(directory)):
        # 匹配 2026-XX.csv 格式
        if filename.startswith("2026-") and filename.endswith(".csv"):
            try:
                month = int(filename.split("-")[1])
                if start_month <= month <= end_month:
                    file_path = os.path.join(directory, filename)
                    with open(file_path, 'r', encoding='utf-8') as f:
                        # 跳过表头
                        next(f)
                        for line in f:
                            line = line.strip()
                            if not line:
                                continue
                            # 假设每行是以逗号分隔，最后一列是金额
                            parts = line.split(',')
                            if parts:
                                try:
                                    amount = float(parts[-1])
                                    total_sum += amount
                                    files_processed += 1
                                except ValueError:
                                    continue
            except (ValueError, IndexError):
                continue

    return total_sum

def main():
    sales_dir = 'sales'
    start_m = 1
    end_m = 5
    output_file = 'summary.txt'

    total = calculate_total_sales(sales_dir, start_m, end_m)

    result_text = f"2026年1–5月合计: {total:.2f}\n"

    with open(output_file, 'w', encoding='utf-8') as f:
        f.write(result_text)

    print(f"计算完成。总额: {total:.2f}，已写入 {output_file}")

if __name__ == "__main__":
    main()

