                for line in f:
                    line = line.strip()
                    if not line:
                        continue
                    parts = line.split(',')
                    if parts:
                        try:
                            amount = float(parts[-1])
                            total_amount += amount
                        except ValueError:
                            pass
            files_processed += 1

    return total_amount

